  "commands": [
    {
      "keystrokes": "cat > solution.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n, m, q;\n    if(!(cin >> n >> m >> q)) return 0;\n    vector<long long> a(n+1);\n    for(int i = 1; i <= n; ++i) cin >> a[i];\n\n    vector<vector<int>> sets(m+1);\n    int totalSize = 0;\n    for(int k = 1; k <= m; ++k){\n        int sz; cin >> sz;\n        sets[k].resize(sz);\n        for(int j = 0; j < sz; ++j){\n            int idx; cin >> idx;\n            sets[k][j] = idx;\n        }\n        totalSize += sz;\n    }\n\n    int B = (int)sqrt((double)totalSize) + 1;\n    if(B < 1) B = 1;\n\n    vector<char> isBig(m+1,false);\n    vector<int> bigIndex(m+1,-1);\n    vector<vector<int>> bigSets;\n\n    for(int k = 1; k <= m; ++k){\n        if((int)sets[k].size() > B){\n            bigIndex[k] = (int)bigSets.size();\n            isBig[k] = true;\n            bigSets.push_back(sets[k]);\n        }\n    }\n\n    int numBig = (int)bigSets.size();\n\n    // bigInElem: for each element, which big sets contain it\n    vector<vector<int>> bigInElem(n+1);\n    for(int bi = 0; bi < numBig; ++bi){\n        for(int idx : bigSets[bi]){\n            bigInElem[idx].push_back(bi);\n        }\n    }\n\n    // interCounts[k][bi] = |Sk ∩ BigSet[bi]|\n    vector<vector<int>> interCounts(m+1, vector<int>(numBig, 0));\n    for(int k = 1; k <= m; ++k){\n        for(int idx : sets[k]){\n            for(int bi : bigInElem[idx]){\n                interCounts[k][bi]++;\n            }\n        }\n    }\n\n    // interBigMatrix[bi][bj] = |BigSet[bi] ∩ BigSet[bj]|\n    vector<vector<int>> interBigMatrix(numBig, vector<int>(numBig, 0));\n    for(int i = 1; i <= n; ++i){\n        auto &L = bigInElem[i];\n        int sz = (int)L.size();\n        for(int p = 0; p < sz; ++p){\n            int bi = L[p];\n            for(int q = 0; q < sz; ++q){\n                int bj = L[q];\n                interBigMatrix[bi][bj]++;\n            }\n        }\n    }\n\n    // Initialize sumBigVal for big sets and addBig (lazy per-element add from big sets)\n    vector<long long> sumBigVal(numBig, 0);\n    for(int bi = 0; bi < numBig; ++bi){\n        long long s = 0;\n        for(int idx : bigSets[bi]) s += a[idx];\n        sumBigVal[bi] = s;\n    }\n    vector<long long> addBig(numBig, 0);\n\n    // Process queries\n    for(int qi = 0; qi < q; ++qi){\n        char op; cin >> op;\n        if(op == '?'){\n            int k; cin >> k;\n            if(isBig[k]){\n                int bi = bigIndex[k];\n                cout << sumBigVal[bi] << \"\\n\";\n            } else {\n                long long res = 0;\n                for(int idx : sets[k]) res += a[idx];\n                for(int bi = 0; bi < numBig; ++bi){\n                    long long ic = interCounts[k][bi];\n                    if(ic) res += addBig[bi] * ic;\n                }\n                cout << res << \"\\n\";\n            }\n        } else if(op == '+'){\n            int k; long long x; cin >> k >> x;\n            if(isBig[k]){\n                int bk = bigIndex[k];\n                addBig[bk] += x;\n                if(numBig > 0){\n                    for(int bi = 0; bi < numBig; ++bi){\n                        sumBigVal[bi] += x * (long long)interBigMatrix[bi][bk];\n                    }\n                }\n            } else {\n                for(int idx : sets[k]) a[idx] += x;\n                if(numBig > 0){\n                    for(int bi = 0; bi < numBig; ++bi){\n                        sumBigVal[bi] += x * (long long)interCounts[k][bi];\n                    }\n                }\n            }\n        }\n    }\n\n    return 0;\n}\nCPP\n"},
